import Foundation
private let offset: UInt64 = 1_469_598_103_934_665_603
private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for index in 0..<8 { result ^= (value >> UInt64(index * 8)) & 255; result &*= prime }; return result }
private func row(_ output: SM64UnusedPoundablePlatformOutput) -> [UInt64] { [UInt64(bitPattern: Int64(output.action)), UInt64(bitPattern: Int64(output.timer)), UInt64(output.scale.bitPattern), output.spawnMistParticles ? 1 : 0, output.spawnTriangleParticles ? 1 : 0, output.loadCollisionModel ? 1 : 0, output.shouldDelete ? 1 : 0] }
@main struct SM64UnusedPoundablePlatformSmoke { static func main() { let idle = SM64UnusedPoundablePlatformBehavior.update(.init(action: 0, timer: 0, marioGroundPounded: false)); let pound = SM64UnusedPoundablePlatformBehavior.update(.init(action: 0, timer: 1, marioGroundPounded: true)); let gone = SM64UnusedPoundablePlatformBehavior.update(.init(action: 1, timer: 8, marioGroundPounded: false)); precondition(idle.action == 0 && idle.timer == 1 && idle.loadCollisionModel); precondition(pound.action == 1 && pound.spawnMistParticles && pound.spawnTriangleParticles); precondition(gone.shouldDelete); var fingerprint = offset; for output in [idle, pound, gone] { for value in row(output) { fingerprint = hash(fingerprint, value) } }; print(String(format: "unusedPoundablePlatformFingerprint=0x%016llx", fingerprint)); print("SM64 Modern unused poundable platform smoke passed") } }
